// Site-wide search. nav.js loads this on demand (header button, Ctrl/Cmd+K,
// or "/"); search.html loads it directly. The index, /api/search.json, is
// generated by scripts/build-site.js from every course, bundle, page, FAQ
// answer, and glossary term, so new pages are searchable after the next build.
(function () {
  'use strict';
  if (window.DCTSearch) return;

  var INDEX_URL = '/api/search.json';
  var TYPE_ORDER = ['Course', 'Bundle', 'Guide', 'Glossary', 'Careers', 'Quiz', 'Tool', 'FAQ', 'Blog', 'Page'];
  var TYPE_LABEL = { Course: 'Courses', Bundle: 'Bundles', Guide: 'Guides', Glossary: 'Glossary', Careers: 'Careers', Quiz: 'Quizzes', Tool: 'Tools', FAQ: 'FAQ', Blog: 'Blog', Page: 'Pages' };
  // Courses rank a little higher: they are what most searches are looking for.
  var TYPE_BOOST = { Course: 4, Bundle: 2, Guide: 3, Tool: 2, Quiz: 2, Careers: 2, Glossary: 1, FAQ: 1, Blog: 0, Page: 0 };
  var STOPWORDS = { a: 1, an: 1, and: 1, are: 1, as: 1, at: 1, be: 1, by: 1, can: 1, do: 1, does: 1, for: 1, how: 1, i: 1, in: 1, is: 1, it: 1, me: 1, my: 1, of: 1, on: 1, or: 1, the: 1, to: 1, what: 1, when: 1, where: 1, which: 1, who: 1, why: 1, with: 1, you: 1, your: 1 };
  // Abbreviations and everyday words mapped to the terms the site uses.
  var SYNONYMS = {
    ups: ['uninterruptible power supply'], pue: ['power usage effectiveness'], dcim: ['data center infrastructure management'],
    bms: ['building management system', 'building automation'], bas: ['building automation'], epo: ['emergency power off'],
    ats: ['automatic transfer switch'], sts: ['static transfer switch'], pdu: ['power distribution unit'], rpp: ['remote power panel'],
    crac: ['computer room air conditioner'], crah: ['computer room air handler'], loto: ['lockout', 'tagout'], ppe: ['personal protective equipment'],
    hvac: ['cooling', 'heating ventilation'], mop: ['method of procedure'], sop: ['standard operating procedure'], eop: ['emergency operating procedure'],
    cx: ['commissioning'], noc: ['network operations center'], bess: ['battery energy storage'], li: ['lithium'], lithium: ['li-ion'],
    dr: ['disaster recovery'], bc: ['business continuity'], rto: ['recovery time objective'], rpo: ['recovery point objective'],
    job: ['career', 'role'], jobs: ['career', 'role'], salary: ['career', 'pay'], hiring: ['career'], work: ['career', 'job'],
    test: ['quiz'], exam: ['quiz'], calculator: ['tool', 'calculate'], calculate: ['calculator'], price: ['pricing', 'cost'], cost: ['price', 'pricing'],
    cert: ['certificate', 'certification'], certification: ['certificate'], certified: ['certificate'], ceu: ['continuing education'],
    tier3: ['tier iii'], tier4: ['tier iv'], electrician: ['electrical'], electric: ['electrical'], ac: ['cooling'], chiller: ['chilled water'],
    ai: ['artificial intelligence', 'gpu', 'high density'], gpu: ['ai', 'high density'], liquid: ['liquid cooling', 'immersion'],
    osha: ['occupational safety'], nfpa: ['national fire protection'], fire: ['suppression'], security: ['access control'], badge: ['access control']
  };

  var indexPromise = null;
  var regexCache = {};
  var exactCache = {};

  function norm(s) {
    return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9.+#/\- ]+/g, ' ');
  }

  function load() {
    if (!indexPromise) {
      indexPromise = fetch(INDEX_URL, { credentials: 'omit' })
        .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then(function (data) {
          data.docs.forEach(function (d, i) {
            d.i = i;
            d._t = norm(d.t); d._k = norm(d.k); d._d = norm(d.d); d._b = norm(d.b);
          });
          return data.docs;
        })
        .catch(function (err) { indexPromise = null; throw err; });
    }
    return indexPromise;
  }

  function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

  // Matches a term at the start of a word, so "ups" finds "UPS" but not "groups".
  function wordRe(term) {
    if (!regexCache[term]) regexCache[term] = new RegExp('(^|[^a-z0-9])' + escapeRe(term));
    return regexCache[term];
  }

  // The whole word, for a small bonus when a title uses exactly the term searched.
  function exactRe(term) {
    if (!exactCache[term]) exactCache[term] = new RegExp('(^|[^a-z0-9])' + escapeRe(term) + '($|[^a-z0-9])');
    return exactCache[term];
  }

  function tokenize(q) {
    var words = norm(q).split(/\s+/).filter(Boolean);
    var meaningful = words.filter(function (w) { return !STOPWORDS[w]; });
    return meaningful.length ? meaningful : words;
  }

  function alternatives(token) {
    var alts = [token];
    if (token.length > 4 && /s$/.test(token)) alts.push(token.replace(/(es|s)$/, ''));
    (SYNONYMS[token] || []).forEach(function (s) { alts.push(norm(s)); });
    return alts;
  }

  function scoreToken(doc, alts) {
    var best = 0;
    for (var i = 0; i < alts.length; i++) {
      var re = wordRe(alts[i]);
      var weight = i === 0 ? 1 : 0.8;
      var s = 0;
      if (re.test(doc._t)) s = 12 + (exactRe(alts[i]).test(doc._t) ? 4 : 0);
      else if (re.test(doc._k)) s = 6;
      else if (re.test(doc._d)) s = 4;
      else if (re.test(doc._b)) s = 2;
      if (s * weight > best) best = s * weight;
    }
    return best;
  }

  function search(docs, q) {
    var tokens = tokenize(q);
    if (!tokens.length) return { results: [], partial: false };
    var phrase = norm(q).trim();
    var tokenAlts = tokens.map(alternatives);
    var run = function (requireAll) {
      var out = [];
      docs.forEach(function (doc) {
        var total = 0, matched = 0;
        for (var i = 0; i < tokenAlts.length; i++) {
          var s = scoreToken(doc, tokenAlts[i]);
          if (s) { total += s; matched++; } else if (requireAll) return;
        }
        if (!matched) return;
        if (phrase.length > 2 && tokens.length > 1) {
          if (doc._t.indexOf(phrase) !== -1) total += 20;
          else if (doc._k.indexOf(phrase) !== -1 || doc._d.indexOf(phrase) !== -1) total += 8;
        }
        if (doc._t.indexOf(phrase) === 0) total += 10;
        total += TYPE_BOOST[doc.y] || 0;
        if (!requireAll) total *= matched / tokenAlts.length;
        out.push({ doc: doc, score: total });
      });
      out.sort(function (a, b) { return b.score - a.score || a.doc.i - b.doc.i; });
      return out;
    };
    var results = run(true);
    var partial = false;
    if (!results.length && tokens.length > 1) { results = run(false); partial = results.length > 0; }
    return { results: results, partial: partial, tokens: tokens };
  }

  function escapeHtml(s) {
    return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function highlight(text, tokens) {
    var html = escapeHtml(text);
    var terms = (tokens || []).filter(function (t) { return t.length > 1; }).map(escapeRe);
    if (!terms.length) return html;
    return html.replace(new RegExp('(^|[^a-z0-9])(' + terms.join('|') + ')', 'gi'), '$1<mark>$2</mark>');
  }

  function hitHtml(doc, tokens, id) {
    return '<a class="search-hit" href="/' + escapeHtml(doc.u) + '"' + (id ? ' id="' + id + '" role="option" aria-selected="false"' : '') + '>' +
      '<span class="search-hit-top"><span class="search-hit-type" data-type="' + doc.y + '">' + doc.y + '</span>' +
      '<span class="search-hit-title">' + highlight(doc.t, tokens) + '</span></span>' +
      (doc.d ? '<span class="search-hit-desc">' + highlight(doc.d, tokens) + '</span>' : '') +
      (doc.m ? '<span class="search-hit-meta">' + escapeHtml(doc.m) + '</span>' : '') +
      '</a>';
  }

  function track(q, count) {
    if (typeof window.gtag === 'function' && q) window.gtag('event', 'search', { search_term: q, results: count });
  }

  var POPULAR = ['UPS', 'Arc flash', 'PUE', 'Tier III', 'Generator', 'Lithium-ion', 'Careers', 'Quiz', 'Fire suppression', 'Glossary'];
  var QUICK_LINKS = [
    ['courses.html', 'Course Catalog', 'Page'],
    ['learn/', 'Knowledge Center', 'Guide'],
    ['quizzes/career-quiz.html', 'Which Data Center Career Fits You?', 'Quiz'],
    ['tools/training-plan-builder.html', 'Training Plan Builder', 'Tool'],
    ['careers/', 'Data Center Careers', 'Careers'],
    ['bundles.html', 'Course Bundles', 'Bundle']
  ];

  // ── Dialog ────────────────────────────────────────────────────────────
  var overlay, input, list, seeAll, lastFocus, active = -1, current = [], debounce;

  function build() {
    overlay = document.createElement('div');
    overlay.className = 'search-overlay';
    overlay.hidden = true;
    overlay.innerHTML =
      '<div class="search-dialog" role="dialog" aria-modal="true" aria-label="Search datacentertraining.us">' +
        '<form class="search-bar" role="search" action="/search.html" method="get">' +
          '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>' +
          '<input type="search" name="q" id="siteSearchInput" placeholder="Search courses, guides, careers, quizzes..." autocomplete="off" spellcheck="false" ' +
            'role="combobox" aria-expanded="true" aria-controls="siteSearchResults" aria-autocomplete="list" aria-label="Search the site">' +
          '<button type="button" class="search-close" aria-label="Close search">Esc</button>' +
        '</form>' +
        '<div class="search-body"><div id="siteSearchResults" role="listbox" aria-label="Search results"></div></div>' +
        '<div class="search-foot"><span class="search-keys"><kbd class="search-kbd">&uarr;</kbd> <kbd class="search-kbd">&darr;</kbd> to move, <kbd class="search-kbd">Enter</kbd> to open</span><a href="/search.html" id="siteSearchAll">See all results &rarr;</a></div>' +
      '</div>';
    document.body.appendChild(overlay);
    input = overlay.querySelector('input');
    list = overlay.querySelector('#siteSearchResults');
    seeAll = overlay.querySelector('#siteSearchAll');

    overlay.addEventListener('mousedown', function (e) { if (e.target === overlay) close(); });
    overlay.querySelector('.search-close').addEventListener('click', close);
    input.addEventListener('input', function () {
      clearTimeout(debounce);
      debounce = setTimeout(render, 60);
    });
    input.addEventListener('keydown', function (e) {
      var hits = list.querySelectorAll('.search-hit');
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        if (!hits.length) return;
        e.preventDefault();
        active = e.key === 'ArrowDown' ? (active + 1) % hits.length : (active <= 0 ? hits.length - 1 : active - 1);
        select(hits);
      } else if (e.key === 'Enter') {
        if (active >= 0 && hits[active]) {
          e.preventDefault();
          track(input.value.trim(), current.length);
          window.location.href = hits[active].href;
        } else {
          track(input.value.trim(), current.length);
        }
      }
    });
    overlay.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { e.preventDefault(); close(); }
      else if (e.key === 'Tab') {
        // Keep focus inside the dialog.
        var f = overlay.querySelectorAll('input, button, a[href]');
        var first = f[0], last = f[f.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    });
    list.addEventListener('click', function (e) {
      var chip = e.target.closest('[data-q]');
      if (chip) { e.preventDefault(); input.value = chip.getAttribute('data-q'); input.focus(); render(); return; }
      if (e.target.closest('.search-hit')) track(input.value.trim(), current.length);
    });
  }

  function select(hits) {
    hits.forEach(function (h, i) { h.setAttribute('aria-selected', i === active ? 'true' : 'false'); });
    if (hits[active]) {
      input.setAttribute('aria-activedescendant', hits[active].id);
      hits[active].scrollIntoView({ block: 'nearest' });
    } else {
      input.removeAttribute('aria-activedescendant');
    }
  }

  function emptyState() {
    return '<div class="search-section-label">Popular searches</div>' +
      '<div class="search-chips">' + POPULAR.map(function (p) { return '<button type="button" class="search-chip" data-q="' + p + '">' + p + '</button>'; }).join('') + '</div>' +
      '<div class="search-section-label">Quick links</div>' +
      QUICK_LINKS.map(function (l, i) { return hitHtml({ u: l[0], t: l[1], y: l[2] }, [], 'sr-' + i); }).join('');
  }

  function render() {
    var q = input.value.trim();
    active = -1;
    input.removeAttribute('aria-activedescendant');
    seeAll.href = '/search.html' + (q ? '?q=' + encodeURIComponent(q) : '');
    if (!q) { current = []; list.innerHTML = emptyState(); return; }
    load().then(function (docs) {
      if (input.value.trim() !== q) return;
      var r = search(docs, q);
      current = r.results;
      if (!current.length) {
        list.innerHTML = '<div class="search-empty">No results for <strong>' + escapeHtml(q) + '</strong>. Try a shorter word, or browse the <a href="/courses.html">course catalog</a> or the <a href="/learn/">Knowledge Center</a>. Need a course we don\'t offer? <a href="/course-request.html?topic=' + encodeURIComponent(q) + '">Request it</a>.</div>' +
          '<div class="search-section-label">Try</div><div class="search-chips">' + POPULAR.slice(0, 6).map(function (p) { return '<button type="button" class="search-chip" data-q="' + p + '">' + p + '</button>'; }).join('') + '</div>';
        return;
      }
      list.innerHTML = (r.partial ? '<div class="search-section-label">Closest matches</div>' : '') +
        current.slice(0, 12).map(function (x, i) { return hitHtml(x.doc, r.tokens, 'sr-' + i); }).join('');
      seeAll.textContent = 'See all ' + current.length + ' results →';
    }).catch(function () {
      list.innerHTML = '<div class="search-empty">Search is unavailable right now. <a href="/search.html?q=' + encodeURIComponent(q) + '">Try the search page</a>.</div>';
    });
  }

  function open(q) {
    if (!overlay) build();
    lastFocus = document.activeElement;
    overlay.hidden = false;
    document.body.classList.add('search-open');
    if (typeof q === 'string') input.value = q;
    input.focus();
    input.select();
    render();
    load().catch(function () {});
  }

  function close() {
    if (!overlay || overlay.hidden) return;
    overlay.hidden = true;
    document.body.classList.remove('search-open');
    if (lastFocus && lastFocus.focus) lastFocus.focus();
  }

  // ── Full results page (search.html) ───────────────────────────────────
  function initPage() {
    var root = document.getElementById('searchPage');
    if (!root) return;
    var form = root.querySelector('form');
    var field = root.querySelector('input[name="q"]');
    var filters = root.querySelector('.search-filters');
    var status = root.querySelector('.search-status');
    var out = root.querySelector('.search-page-results');
    var more = root.querySelector('.search-more');
    var params = new URLSearchParams(window.location.search);
    var type = params.get('type') || 'all';
    var shown = 20;
    var lastResults = null;
    field.value = params.get('q') || '';

    function draw() {
      if (!lastResults) return;
      var counts = {};
      lastResults.results.forEach(function (x) { counts[x.doc.y] = (counts[x.doc.y] || 0) + 1; });
      var types = TYPE_ORDER.filter(function (t) { return counts[t]; });
      if (type !== 'all' && !counts[type]) type = 'all';
      filters.innerHTML = lastResults.results.length
        ? '<button type="button" class="search-filter" data-type="all" aria-pressed="' + (type === 'all') + '">All <span>' + lastResults.results.length + '</span></button>' +
          types.map(function (t) { return '<button type="button" class="search-filter" data-type="' + t + '" aria-pressed="' + (type === t) + '">' + TYPE_LABEL[t] + ' <span>' + counts[t] + '</span></button>'; }).join('')
        : '';
      var list = lastResults.results.filter(function (x) { return type === 'all' || x.doc.y === type; });
      var q = field.value.trim();
      if (!q) {
        status.textContent = 'Search every course, guide, career page, quiz, tool, FAQ answer, and glossary term.';
        out.innerHTML = QUICK_LINKS.map(function (l) { return hitHtml({ u: l[0], t: l[1], y: l[2] }, []); }).join('');
        more.hidden = true;
        return;
      }
      if (!list.length) {
        status.innerHTML = 'No results for <strong>' + escapeHtml(q) + '</strong>. Check the spelling, try fewer words, or call <a href="tel:18664296742">1-866-429-6742</a> and we will point you to the right course. Need a course we don\'t offer? <a href="/course-request.html?topic=' + encodeURIComponent(q) + '">Request it</a>.';
        out.innerHTML = QUICK_LINKS.map(function (l) { return hitHtml({ u: l[0], t: l[1], y: l[2] }, []); }).join('');
        more.hidden = true;
        return;
      }
      status.innerHTML = (lastResults.partial ? 'No exact match. Closest ' : '') + list.length + (list.length === 1 ? ' result' : ' results') + ' for <strong>' + escapeHtml(q) + '</strong>';
      out.innerHTML = list.slice(0, shown).map(function (x) { return hitHtml(x.doc, lastResults.tokens); }).join('');
      more.hidden = list.length <= shown;
    }

    function run(push) {
      var q = field.value.trim();
      shown = 20;
      var url = '/search.html' + (q ? '?q=' + encodeURIComponent(q) + (type !== 'all' ? '&type=' + type : '') : '');
      if (push) history.replaceState(null, '', url);
      document.title = (q ? q + ' - ' : '') + 'Search | Data Center Training';
      if (!q) { lastResults = { results: [], partial: false, tokens: [] }; draw(); return; }
      status.textContent = 'Searching...';
      load().then(function (docs) {
        lastResults = search(docs, q);
        draw();
        track(q, lastResults.results.length);
      }).catch(function () {
        status.textContent = 'Search is unavailable right now. Please try again, or browse the course catalog.';
      });
    }

    form.addEventListener('submit', function (e) { e.preventDefault(); type = 'all'; run(true); });
    field.addEventListener('input', function () { clearTimeout(debounce); debounce = setTimeout(function () { run(true); }, 150); });
    filters.addEventListener('click', function (e) {
      var b = e.target.closest('.search-filter');
      if (!b) return;
      type = b.getAttribute('data-type');
      shown = 20;
      draw();
      var q = field.value.trim();
      history.replaceState(null, '', '/search.html?q=' + encodeURIComponent(q) + (type !== 'all' ? '&type=' + type : ''));
    });
    more.querySelector('button').addEventListener('click', function () { shown += 20; draw(); });
    run(false);
  }

  window.DCTSearch = { open: open, close: close, load: load, search: function (q) { return load().then(function (docs) { return search(docs, q); }); } };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initPage);
  else initPage();
})();
